import sys

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        return
    s1 = lines[0]
    s2 = lines[1]

    common_len = 0
    for c1, c2 in zip(s1, s2):
        if c1 == c2:
            common_len += 1
        else:
            break

    print(common_len)

if __name__ == '__main__':
    main()

